static void sub(V *d,const V *a,const V *b) { if((a==b||(a->id&&a->id==b->id))&&mpfr_number_p(a->l)&&mpfr_number_p(a->h)){mpfr_set_zero(d->l,0);mpfr_set_zero(d->h,0);}else{mpfr_sub(d->l,a->l,b->h,MPFR_RNDD);mpfr_sub(d->h,a->h,b->l,MPFR_RNDU);}d->id=0; }
