static void monotone(V *d,const V *a,int (*fn)(mpfr_ptr,mpfr_srcptr,mpfr_rnd_t),bool decreasing) { d->id=0; fn(d->l,decreasing?a->h:a->l,MPFR_RNDD);fn(d->h,decreasing?a->l:a->h,MPFR_RNDU); }
static void sine(V *d,const V *a,bool cosine) { /* Global derivative bound one encloses every finite interval. */
    if(cosine){mpfr_cos(d->l,a->l,MPFR_RNDD);mpfr_cos(d->h,a->l,MPFR_RNDU);}else{mpfr_sin(d->l,a->l,MPFR_RNDD);mpfr_sin(d->h,a->l,MPFR_RNDU);}mpfr_sub(temp[10].h,a->h,a->l,MPFR_RNDU);mpfr_sub(d->l,d->l,temp[10].h,MPFR_RNDD);mpfr_add(d->h,d->h,temp[10].h,MPFR_RNDU);if(mpfr_cmp_si(d->l,-1)<0)mpfr_set_si(d->l,-1,MPFR_RNDN);if(mpfr_cmp_si(d->h,1)>0)mpfr_set_si(d->h,1,MPFR_RNDN); }
