/* A poisoned predicate cannot select a path. Independently prove a pure DAG
   postdominator, then poison the whole skipped region and its join phis. */
static uint32_t successor(CSOsdiPrecisionBlock b,unsigned edge,uint32_t exit) {
    if(b.terminator==0)return exit;
    if(b.terminator==1)return b.then_block;
    if(b.terminator==2)return edge?b.else_block:b.then_block;
    die("terminator");
}
