        for(uint32_t j=0;j<b.instruction_count;j++){tick();CSOsdiPrecisionInstruction q=instructions[b.first_instruction+j];if(q.opcode==73)die("deferred_effect");if(q.destination>=p->registers.count)die("destination");r[q.destination].valid=true;r[q.destination].status=1;r[q.destination].id=0;}
        for(uint32_t j=0;j<b.phi_edge_count;j++){tick();uint32_t d=phis[b.first_phi_edge+j].destination;if(d>=p->registers.count)die("phi_destination");r[d].valid=true;r[d].status=1;r[d].id=0;}
